get_current_member_profile.afterResponse:
var profile = response || {};
var locale = profile.locale;
var readLocale = () => {
  if (typeof locale === 'string') return locale;
  if (typeof locale === 'object' && locale !== null) {
    if (typeof locale.language === 'string' && typeof locale.country === 'string') return locale.language + '_' + locale.country;
    if (typeof locale.language === 'string') return locale.language;
  }
  return null;
};
var or = (value) => value === undefined || value === null ? null : value;
return {
  sub: or(profile.sub),
  member_urn: profile.sub ? 'urn:li:person:' + profile.sub : null,
  name: or(profile.name),
  given_name: or(profile.given_name),
  family_name: or(profile.family_name),
  email: or(profile.email),
  email_verified: or(profile.email_verified),
  picture: or(profile.picture),
  locale: readLocale()
};

list_managed_organizations.afterResponse:
var headers = { 'X-Restli-Protocol-Version': '2.0.0', 'LinkedIn-Version': '202511' };
var elements = [];
var page = response || {};
var start = 0;
for (var index = 0; index < 20; index++) {
  if (index > 0) page = call({ method: 'GET', url: '/rest/organizationAcls', headers: headers, query: { q: 'roleAssignee', role: 'ADMINISTRATOR', state: 'APPROVED', start: String(start), count: '100' } });
  var found = page.elements || [];
  elements.push(...found);
  if (found.length === 0) break;
  var links = page.paging && Array.isArray(page.paging.links) ? page.paging.links : null;
  var next = links === null ? null : links.some((link) => link.rel === 'next');
  if (next === false || (next === null && found.length < 100)) break;
  start += found.length;
}
var idOf = (urn) => urn.substring(urn.lastIndexOf(':') + 1);
var seen = {};
var rows = elements.map((element) => ({
  organization_urn: element.organizationTarget || element.organization || element.organizationalTarget || null,
  role: element.role === undefined ? null : element.role,
  state: element.state === undefined ? null : element.state
})).filter((row) => {
  if (row.organization_urn === null || seen[row.organization_urn]) return false;
  seen[row.organization_urn] = true;
  return true;
});
if (elements.length > 0 && rows.length === 0) throw new Error('LinkedIn returned ' + elements.length + ' organization role assignment(s) but none carried a recognised organization URN, so no organization id could be resolved. The keys present on the first entry were: ' + Object.keys(elements[0]).join(', ') + '. This is an API shape change, not an empty account.');
if (rows.length === 0) return { organizations: [], count: 0 };
var ids = rows.map((row) => idOf(String(row.organization_urn)));
var results = {};
for (var at = 0; at < ids.length; at += 50) {
  var lookup = call({ method: 'GET', url: '/rest/organizations?ids=List(' + ids.slice(at, at + 50).map(encodeURIComponent).join(',') + ')', headers: headers });
  Object.assign(results, lookup.results || {});
}
var or = (value) => value === undefined || value === null ? null : value;
var organizations = rows.map((row) => {
  var id = idOf(String(row.organization_urn));
  var organization = results[id] || {};
  return { organization_urn: row.organization_urn, organization_id: id, name: or(organization.localizedName), vanity_name: or(organization.vanityName), website: or(organization.localizedWebsite), role: row.role, state: row.state };
});
return { organizations: organizations, count: organizations.length };

update_post_commentary.beforeRequest:
var patch = {};
if (inputs.commentary) patch.commentary = inputs.commentary.replace(/[\(*\)\[\]\{\}<>@|~_]/gm, (x) => '\\' + x);
if (inputs.content_call_to_action_label) patch.contentCallToActionLabel = inputs.content_call_to_action_label;
if (inputs.content_landing_page) patch.contentLandingPage = inputs.content_landing_page;
if (Object.keys(patch).length === 0) throw new Error('Nothing to update. Supply at least one of Commentary, Call To Action Label or Landing Page URL.');
request.body = { patch: { $set: patch } };
return request;

update_post_commentary.afterResponse:
var fields = [];
if (inputs.commentary) fields.push('commentary');
if (inputs.content_call_to_action_label) fields.push('contentCallToActionLabel');
if (inputs.content_landing_page) fields.push('contentLandingPage');
return { success: true, post_urn: inputs.post_urn, updated_fields: fields.join(', '), updated_field_count: fields.length };

create_image_upload_url.afterResponse:
var value = (response && response.value) || {};
var or = (item) => item === undefined || item === null ? null : item;
return { owner_urn: inputs.owner_urn, image_urn: or(value.image), upload_url: or(value.uploadUrl), upload_url_expires_at: or(value.uploadUrlExpiresAt) };
